import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.dgpN-s4-.js";var i=JSON.parse(`{"title":"Data catalogue and financial assumptions audit","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/DATA-AND-FINANCIAL-ASSUMPTIONS.html"}],["meta",{"property":"og:title","content":"Data catalogue and financial assumptions audit | FD Cal Documentation"}],["meta",{"property":"og:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}],["meta",{"property":"og:url","content":"https://aaron-fredrick.github.io/FD-Calculator/FD-Calculator/dev/docs/audits/DATA-AND-FINANCIAL-ASSUMPTIONS.html"}],["meta",{"name":"twitter:title","content":"Data catalogue and financial assumptions audit | FD Cal Documentation"}],["meta",{"name":"twitter:description","content":"FD Cal documentation for fixed-deposit planning, investment strategies, bank product data and the shared simulation engine."}]]},"headers":[],"relativePath":"audits/DATA-AND-FINANCIAL-ASSUMPTIONS.md","filePath":"audits/DATA-AND-FINANCIAL-ASSUMPTIONS.md","lastUpdated":1794184492000}`),a={name:`audits/DATA-AND-FINANCIAL-ASSUMPTIONS.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="data-catalogue-and-financial-assumptions-audit" tabindex="-1">Data catalogue and financial assumptions audit <a class="header-anchor" href="#data-catalogue-and-financial-assumptions-audit" aria-label="Permalink to “Data catalogue and financial assumptions audit”">​</a></h1><h2 id="data-01-—-product-source-provenance-is-not-visible-in-the-user-facing-workflow" tabindex="-1">DATA-01 — Product-source provenance is not visible in the user-facing workflow <a class="header-anchor" href="#data-01-—-product-source-provenance-is-not-visible-in-the-user-facing-workflow" aria-label="Permalink to “DATA-01 — Product-source provenance is not visible in the user-facing workflow”">​</a></h2><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong></p><ul><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/data/fd_options/fd_options.csv" target="_blank" rel="noreferrer">fd_options.csv</a> contains <code>research_status</code> and <code>research_notes</code>.</li><li>Per-bank product CSVs contain <code>source_url</code>, <code>source_effective_date</code>, <code>source_type</code> and notes.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L57-L61" target="_blank" rel="noreferrer">app.js L57-L61</a> uses the index status to disable only banks with <code>no_public_rate_verified</code>; it does not display the remaining source status or notes.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L78" target="_blank" rel="noreferrer">app.js L78</a> constructs FDOption objects from the product terms but does not retain source URL, effective date or research metadata.</li><li><a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/io/data-loader.js#L11" target="_blank" rel="noreferrer">data-loader.js L11</a> likewise maps the simulation terms into FDOption without source provenance.</li></ul><p><strong>Impact:</strong> products backed by a direct official schedule, a secondary compilation, or a source with no effective date can appear as equivalent options. The catalogue&#39;s internal research notes already distinguish these cases, but users cannot assess the evidence quality at the point of comparison.</p><p><strong>Recommendation:</strong> add a separate immutable provenance object to each product, not financial calculation fields. Show source type, source link, effective date (or “not published”), last-reviewed date and research caveat in the product details and standalone report. Visibly distinguish direct official data from secondary/unverified inputs. Preserve provenance through worker serialization and report generation.</p><h2 id="data-02-—-senior-minor-selection-is-not-an-actual-depositor-eligibility-check" tabindex="-1">DATA-02 — Senior/minor selection is not an actual depositor eligibility check <a class="header-anchor" href="#data-02-—-senior-minor-selection-is-not-an-actual-depositor-eligibility-check" aria-label="Permalink to “DATA-02 — Senior/minor selection is not an actual depositor eligibility check”">​</a></h2><p><strong>Severity: P2</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/configuration.js#L140-L148" target="_blank" rel="noreferrer">configuration.js L140-L148</a> includes senior/minor products when the corresponding boolean is true. The web form stores these booleans in <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/web/app.js#L76-L88" target="_blank" rel="noreferrer">app.js L76-L88</a>. It does not collect depositor age or guardian status. The report explicitly states that catalogue age and guardian conditions are informational and are not verified (<a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/reporting/html.js#L219" target="_blank" rel="noreferrer">html.js L219</a>).</p><p><strong>Impact:</strong> the toggle means “include this customer segment&#39;s products”, not “verify that the depositor qualifies”. A user can include senior/minor rates without the application checking age thresholds, inclusive/exclusive boundaries or guardian requirements.</p><p><strong>Recommendation:</strong> either:</p><ol><li>Add a customer eligibility profile (age on booking date, citizenship/residency where required, guardian confirmation) and enforce catalogue conditions; or</li><li>Rename the controls to make their scope unmistakable (“Include senior-citizen products in the candidate set”) and keep a persistent warning that eligibility is not checked.</li></ol><p>Do not imply that a category toggle is proof of eligibility.</p><h2 id="data-03-—-the-active-fd-model-cannot-yet-represent-all-special-product-constraints" tabindex="-1">DATA-03 — The active FD model cannot yet represent all special-product constraints <a class="header-anchor" href="#data-03-—-the-active-fd-model-cannot-yet-represent-all-special-product-constraints" aria-label="Permalink to “DATA-03 — The active FD model cannot yet represent all special-product constraints”">​</a></h2><p><strong>Evidence:</strong> the research register <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/data/fd_options/age_eligibility.csv" target="_blank" rel="noreferrer">age_eligibility.csv</a> contains fields such as <code>product_max_amount</code> and <code>tax_exempt</code>. The active <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/core/models.js" target="_blank" rel="noreferrer">FDOption model</a> and data loaders currently model minimum amount and age/segment fields, but not product maximum amount or tax-exempt treatment.</p><p><strong>Impact:</strong> products with scheme-wide caps, product caps or special tax treatment must remain excluded from simulation until those rules can be enforced. Reusing general FD rates or minimums for a special product can create an invalid plan.</p><p><strong>Recommendation:</strong> extend the domain model only when a real product requires it: maximum amount, per-customer/scheme-wide cap, tax treatment, required documentation/guardian and any renewal/eligibility conditions. Add validation and tests before moving a research-register row into the active product catalogue.</p><h2 id="data-04-—-csv-rows-are-not-checked-for-exact-field-count" tabindex="-1">DATA-04 — CSV rows are not checked for exact field count <a class="header-anchor" href="#data-04-—-csv-rows-are-not-checked-for-exact-field-count" aria-label="Permalink to “DATA-04 — CSV rows are not checked for exact field count”">​</a></h2><p><strong>Severity: P3</strong></p><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/src/io/csv.js#L6" target="_blank" rel="noreferrer">src/io/csv.js L6</a> maps headers to values with <code>values[i] ?? &quot;&quot;</code>. Surplus values are silently ignored; missing values become empty strings.</p><p><strong>Impact:</strong> a malformed or incorrectly quoted bank row may be partially accepted, with trailing data discarded or missing fields represented as blank. Downstream validation catches some missing financial fields but does not guarantee the row was structurally valid.</p><p><strong>Recommendation:</strong> after parsing each row, require <code>values.length === headers.length</code>; reject malformed quote placement and include filename/row number in the error. Add fixtures for short rows, long rows, embedded commas, escaped quotes, multiline notes and unterminated quotes.</p><h2 id="data-05-—-transfer-fee-assumptions-are-not-a-full-transfer-channel-model" tabindex="-1">DATA-05 — Transfer-fee assumptions are not a full transfer-channel model <a class="header-anchor" href="#data-05-—-transfer-fee-assumptions-are-not-a-full-transfer-channel-model" aria-label="Permalink to “DATA-05 — Transfer-fee assumptions are not a full transfer-channel model”">​</a></h2><p><strong>Evidence:</strong> <a href="https://github.com/aaron-fredrick/FD-Calculator/blob/a455462a959f37db757970d0a3078a4d9a3ef028/data/banks/banks.csv" target="_blank" rel="noreferrer">data/banks/banks.csv</a> records bank fee values and notes that distinguish online/mobile CEFT, OTC, SLIPS, fallback CBSL maxima and assumptions. The active fee model chooses same-bank or domestic inter-bank fees per source bank; it does not model all channels, transaction tiers, customer privileges or limits.</p><p><strong>Impact:</strong> a single fee per bank/channel class can be a useful planning approximation, but it is not a complete bank tariff model. The catalogue itself records conflicts and fallback assumptions (for example, bank-published values that differ from a CBSL digital CEFT maximum).</p><p><strong>Recommendation:</strong> keep the current model labelled “estimated transfer fee”. If channel selection materially changes outcomes, add a transfer method dimension (digital CEFT, OTC CEFT, SLIPS, internal transfer), transaction tier and effective date. Do not resolve contradictory sources by silently selecting one.</p><h2 id="data-06-—-bank-rate-freshness-and-secondary-sources-need-a-visible-warning-policy" tabindex="-1">DATA-06 — Bank-rate freshness and secondary sources need a visible warning policy <a class="header-anchor" href="#data-06-—-bank-rate-freshness-and-secondary-sources-need-a-visible-warning-policy" aria-label="Permalink to “DATA-06 — Bank-rate freshness and secondary sources need a visible warning policy”">​</a></h2><p>The index distinguishes <code>populated_direct</code>, <code>populated_secondary</code>, <code>no_public_rate_verified</code> and other research statuses. The web UI disables only the last category. A populated secondary compilation is usable by the engine but should not look identical to a current official schedule.</p><p><strong>Recommendation:</strong> define a freshness policy: effective date required where available, review age threshold, source priority, fallback handling, and visible warnings for secondary or undated rows. Do not automatically disable all secondary data if it remains useful; make confidence and provenance explicit.</p><h2 id="additional-catalogue-checks" tabindex="-1">Additional catalogue checks <a class="header-anchor" href="#additional-catalogue-checks" aria-label="Permalink to “Additional catalogue checks”">​</a></h2><ul><li>Keep rate rows with unresolved product mapping or minimum amounts out of the simulation catalogue, as current research notes already do.</li><li>Do not infer senior rates from general FD rates.</li><li>Preserve product-level labels and payout frequency; avoid flattening different payout contracts into one option.</li><li>Validate duplicate product identities and suspiciously identical rows during catalogue build.</li><li>Keep bank fees and FD rates independently sourced; a verified rate does not imply a verified fee.</li><li>Treat <code>age_eligibility.csv</code> as a research register until every simulation-critical term is enforceable by the engine.</li></ul>`,32)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};